import { useEffect, useState } from 'react'
import { Card } from '../../components/Card'
import { SafetyMap } from '../../components/safety/SafetyMap'
import { AdminLayout } from '../../layouts/AdminLayout'
import { getAdminSafetyMap, type AdminSafetyMap } from '../../services/safetyService'

const empty: AdminSafetyMap = { zones: [], reports: [], clicks: [], clicksByZone: {}, summary: { totalReports: 0, totalZones: 0, unsafeZones: 0, cautionZones: 0, totalClicks: 0 } }
export function AdminSafetyMapPage() {
  const [data, setData] = useState<AdminSafetyMap>(empty)
  const [error, setError] = useState('')
  useEffect(() => { void getAdminSafetyMap().then(setData).catch((reason) => setError(reason instanceof Error ? reason.message : 'Unable to load safety intelligence.')) }, [])
  return <AdminLayout><section className="operator-page safety-page"><header className="operator-page-heading"><div><p className="eyebrow">Admin console · read only</p><h1>Safety intelligence map.</h1><p>Operational visibility into reports, map interactions and automated decisions. There are no admin controls for safety classification.</p></div></header>{error && <p className="auth-error">{error}</p>}<section className="operator-kpis"><Card className="operator-kpi is-primary"><span>Reports</span><strong>{data.summary.totalReports}</strong><small>User complaints / reports</small></Card><Card className="operator-kpi is-danger"><span>Unsafe zones</span><strong>{data.summary.unsafeZones}</strong><small>Marked automatically</small></Card><Card className="operator-kpi is-warning"><span>Caution zones</span><strong>{data.summary.cautionZones}</strong><small>Marked automatically</small></Card><Card className="operator-kpi is-primary"><span>Map clicks</span><strong>{data.summary.totalClicks}</strong><small>Pin interactions</small></Card></section><Card><SafetyMap zones={data.zones} reports={data.reports} height={620} /></Card><Card className="operator-table-card"><h2>Zone intelligence</h2><div className="operator-table"><div className="operator-table-head"><span>Area</span><span>Reports</span><span>Status</span><span>Confidence</span><span>Reason</span></div>{data.zones.map((zone) => <div className="operator-table-row" key={zone.id}><span>{zone.latitude.toFixed(4)}, {zone.longitude.toFixed(4)}</span><strong>{zone.reportCount}</strong><span className={`safety-status safety-status-${zone.status.toLowerCase()}`}>{zone.status}</span><span>{zone.confidence == null ? '—' : `${Math.round(zone.confidence * 100)}%`}</span><span>{zone.reason || '—'}</span></div>)}{!data.zones.length && <p className="page-copy">No safety zones have been reported yet.</p>}</div></Card><Card className="operator-table-card"><h2>Recent reports</h2><div className="operator-table"><div className="operator-table-head"><span>When</span><span>User</span><span>Category</span><span>Point</span><span>Area status</span></div>{data.reports.slice(0, 100).map((report) => <div className="operator-table-row" key={report.id}><span>{new Date(report.createdAt).toLocaleString()}</span><span>{report.user?.name || report.user?.id || 'Traveler'}</span><span>{report.category}</span><span>{report.latitude.toFixed(5)}, {report.longitude.toFixed(5)}</span><span>{report.zone?.aiStatus || '—'} · {report.zone?.reportCount || 0} reports</span></div>)}</div></Card><Card className="operator-table-card"><h2>Map interaction log</h2><div className="operator-table"><div className="operator-table-head"><span>When</span><span>User ID</span><span>Zone</span><span>Coordinates</span></div>{data.clicks.slice(0,100).map((click) => <div className="operator-table-row" key={click.id}><span>{new Date(click.createdAt).toLocaleString()}</span><span>{click.userId || '—'}</span><span>{click.metadata?.zoneKey ? String(click.metadata.zoneKey) : '—'}</span><span>{click.metadata?.latitude != null && click.metadata?.longitude != null ? `${Number(click.metadata.latitude).toFixed(5)}, ${Number(click.metadata.longitude).toFixed(5)}` : '—'}</span></div>)}{!data.clicks.length && <p className="page-copy">No map interactions have been logged yet.</p>}</div></Card></section></AdminLayout>
}
